"""kernels/muse_attention_decode/measure_verify_v2.py (C27 optional sweep, MEASUREMENT-ONLY, generated by tools/gen_measure_verify_v2.py).

No GPU: file rules, kernel_fn is sonnet_v5 verbatim, generator sync, the 14 KB render. Dev GPU: the study end to end on a small shape (every variant runs, compared with the
reference variant). Last: every variant AOT-compiles for sm_90a through tools/ptx_audit.py's Capture; the BN128 reference is sonnet_v5's own instantiation.
Run: set -o pipefail; tools/heavy.sh .venv/bin/python -m pytest -q tests/test_measure_verify_v2.py"""
import importlib.util
import re
import sys
import time
from pathlib import Path

import pytest
import torch

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / "tools"))

PROBLEM = "muse_attention_decode"
MEAS = ROOT / "kernels" / PROBLEM / "measure_verify_v2.py"
V5 = ROOT / "kernels" / PROBLEM / "sonnet_v5.py"
needs_cuda = pytest.mark.skipif(not torch.cuda.is_available(), reason="needs a CUDA GPU")
SMALL_VERIFY = dict(batch=3, ctx=1800, dist="coherent", heads="tp8", layer="full", page=1, q_len=8, spread="agentic")
SMALL_DECODE = dict(batch=3, ctx=1800, dist="coherent", heads="tp8", layer="full", page=1, spread="agentic")


def _load():
    spec = importlib.util.spec_from_file_location("_measure_verify_v2", MEAS)
    m = importlib.util.module_from_spec(spec)
    m._MV_NO_AUTORUN = True
    spec.loader.exec_module(m)
    return m


@pytest.fixture()
def mod():
    return _load()


def test_source_rules_sync_and_kernel_fn_verbatim():
    src = MEAS.read_text()
    compile(src, "measure_verify_v2.py", "exec")
    lines = src.splitlines()
    assert lines[0] == "# okc: problem=muse_attention_decode" and "MEASUREMENT-ONLY" in lines[1] and "NEVER submit" in lines[1]
    for banned in ("subprocess", "urllib", "requests", "socket", "os.system", "import os", "environ", ".tolist(", "from reference", "import reference", "__import__", "_getframe"):
        assert banned not in src, banned
    import gen_measure_verify_v2 as gen
    assert gen.build() == src, "regenerate: .venv/bin/python tools/gen_measure_verify_v2.py"
    v = V5.read_text().splitlines()
    start = next(i for i, line in enumerate(lines) if line.startswith("# sonnet_v5 (C27)"))
    assert lines[start:start + len(v) - 1] == v[1:], "sonnet_v5 is not embedded verbatim"


def test_budget_cases_and_variants(mod):
    assert mod._MV_BUDGET_S <= 240 and mod._MV_REPS == 5 and len(mod._MV_SEEDS) == 3
    assert [i for i, _, _ in mod._MV_CASES] == [9, 11, 7, 3, 5]
    v = dict(mod._MV_VERIFY)
    assert mod._MV_REF["verify"] in v and mod._MV_REF["decode"] in dict(mod._MV_DECODE)
    assert {"B128S2W4", "B128S4W4", "B128S3W8", "B256S2W8", "B64S4W4"} <= set(v)
    assert {"C128S3W2", "C128S3W4"} <= set(dict(mod._MV_DECODE))


def _fake(mod):
    res = {}
    for idx, label, case in mod._MV_CASES:
        kind = "verify" if case.get("q_len", 1) > 1 else "decode"
        v = {"board": dict(us=[100.0, 101.0, 99.0], err=[], perr=[], ok=[], counts=None, status="ok")}
        for i, (n, _) in enumerate(mod._mv_variants(kind)):
            v[n] = dict(us=[100.0 - 2 * i, 101.0 - 2 * i, 99.0 - 2 * i], err=[1e-5] * 3, perr=[1e-6, None, 1e-6], ok=[True] * 3,
                        counts=dict(regs=255, spills=0, smem=98304, cpasync=48, wgmma=26, mma=0, ex2=84, bar=25) if idx in (9, 3) else None, status="ok")
        res[idx] = dict(label=label, kind=kind, seeds=list(mod._MV_SEEDS), v=v)
    return res


def test_render_size_and_format(mod):
    text = mod._mv_render(_fake(mod), dict(gpu="NVIDIA_H200", ovh=4.6, secs=100.0))
    assert len(text.encode()) <= 14000
    lines = text.splitlines()
    first_b = next(i for i, line in enumerate(lines) if line.startswith("B "))
    assert lines[0].startswith("S attn verify v2:") and all(line[:2] in ("S ", "C ") for line in lines[:first_b])
    assert any(line.startswith("C B128S3W4 regs=255") for line in lines[:first_b]) and any(line.startswith("C C64S3W2 regs=255") for line in lines[:first_b])
    for line in lines[first_b:]:
        assert re.fullmatch(r"B attn #\d+ seed=\d+ \| \w+ (us=\d+\.\d\d( x=\d+\.\d\d)?( err=\S+( BAD)?)?|fail .*)", line), line
    res = _fake(mod)
    mod._MV_SEEDS = tuple(range(40))
    for r in res.values():
        r["seeds"] = list(range(40))
        for x in r["v"].values():
            for k in ("us", "err", "perr", "ok"):
                x[k] = x[k] * 14
    big = mod._mv_render(res, dict(gpu="x", ovh=0.0, secs=1.0))
    assert len(big.encode()) <= 14000 and "dropped for the 14 KB cap" in big


@needs_cuda
def test_study_end_to_end_small_and_budget_guard(mod, capsys, monkeypatch):
    monkeypatch.setattr(mod, "_MV_CASES", [(9, "verify16", SMALL_VERIFY), (3, "decode16", SMALL_DECODE)])
    monkeypatch.setattr(mod, "_MV_SEEDS", (11, 12))
    mod._MV_T0 = time.perf_counter()
    mod._mv_study()
    out = capsys.readouterr().out
    lines = out.splitlines()
    assert lines[0].startswith("S attn verify v2:") and len(out.encode()) <= 14000
    # the dev card has 64 KB of shared memory: the BN256 variants (and anything over that) are reported as `fail OutOfResources`, never silently missing
    for n, _ in mod._MV_VERIFY:
        assert any(re.match(rf"B attn #9 seed=11 \| {n} (us=|fail )", line) for line in lines), n
    for n, _ in mod._MV_DECODE:
        assert any(re.match(rf"B attn #3 seed=11 \| {n} (us=|fail )", line) for line in lines), n
    for n in (mod._MV_REF["verify"], "B64S4W4", mod._MV_REF["decode"]):                  # the configs that fit the dev card must have run
        assert any(re.match(rf"B attn #[93] seed=11 \| {n} us=", line) for line in lines), n
    assert any(re.match(r"B attn #9 seed=11 \| board us=", line) for line in lines)
    assert not any(line.startswith("B ") and line.endswith(" BAD") for line in lines), out
    assert "BAD variants: none" in out
    mod._MV_T0 = time.perf_counter() - mod._MV_BUDGET_S
    t = time.perf_counter()
    mod._mv_study()
    assert time.perf_counter() - t < 30
    out2 = capsys.readouterr().out
    assert out2.startswith("S attn verify v2:") and "skipped (budget)" in out2 and "B attn #9" not in out2


@needs_cuda
def test_reference_variant_is_the_board_config_and_variants_agree(mod):
    for kind, case in (("verify", dict(SMALL_VERIFY, batch=16)), ("decode", SMALL_DECODE)):
        data = mod._tr_generate_input(**case, seed=5)
        board = mod.kernel_fn(data).clone()
        skipped = []
        for name, v in mod._mv_variants(kind):
            cfg = mod._mv_cfg(kind, v)
            pl = mod._mv_plan(data, cfg)
            bufs = mod._mv_bufs(data, pl)
            try:
                mod._mv_launch(data, cfg, kind, pl, bufs)
            except Exception as ex:  # noqa: BLE001
                assert "OutOfResources" in type(ex).__name__ and name != mod._MV_REF[kind], (name, ex)      # dev card: 64 KB of shared memory
                skipped.append(name)
                continue
            torch.cuda.synchronize()
            if name == mod._MV_REF[kind]:
                assert torch.equal(bufs["out"], board), name                 # the reference variant IS what kernel_fn launches (batch 16)
            ok, err, row = mod._mv_cmp(bufs["out"], board)
            assert ok and err < 1e-3, (name, err)


@needs_cuda
def test_all_variants_compile_for_sm90():    # LAST: ptx_audit.Capture patches get_device_capability (cached by Triton's driver for the process)
    from tools import ptx_audit as pa
    mod = _load()
    out = {}
    for kind, case in (("verify", SMALL_VERIFY), ("decode", SMALL_DECODE)):
        data = mod._tr_generate_input(**case, seed=3)
        with pa.Capture() as cap:
            for name, v in mod._mv_variants(kind):
                cfg = mod._mv_cfg(kind, v)
                pl = mod._mv_plan(data, cfg)
                cap.case = name
                mod._mv_launch(data, cfg, kind, pl, mod._mv_bufs(data, pl))
        for r in cap.records:
            if r["name"] != "_reduce_kernel":
                out[r["case"]] = pa.compile_record(r)
    assert set(out) == {n for n, _ in mod._MV_VERIFY} | {n for n, _ in mod._MV_DECODE}
    c = out["B128S3W4"]
    assert (c["regs"], c["spills"], c["smem"]) == (255, 0, 98304)
    assert out["B64S4W4"]["regs"] == 185 and out["C64S3W2"]["regs"] == 205 and out["C64S3W2"]["spills"] == 0
    assert out["B256S2W8"]["spills"] == 0 and out["B256S2W8"]["smem"] <= 227 * 1024      # BN256 fits with 8 warps
    assert out["C128S3W4"]["spills"] == 0 and out["C128S3W2"]["spills"] > 0              # decode BN128 needs 4 warps (2 warps spill)
